+++ b/src/cache.ts
@@ -1,19 +1,50 @@
+import { readFileSync, writeFileSync, existsSync, mkdirSync } from "fs";
+import { join } from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

-const store = new Map<string, Entry>();
+const CACHE_DIR = join(process.cwd(), ".cache");
+const CACHE_FILE = join(CACHE_DIR, "session-store.json");
+
+const ensureCacheDir = (): void => {
+  if (!existsSync(CACHE_DIR)) {
+    mkdirSync(CACHE_DIR, { recursive: true });
+  }
+};
+
+const loadStore = (): Map<string, Entry> => {
+  if (!existsSync(CACHE_FILE)) {
+    return new Map();
+  }
+  try {
+    const data = JSON.parse(readFileSync(CACHE_FILE, "utf-8"));
+    return new Map(data);
+  } catch {
+    return new Map();
+  }
+};
+
+const saveStore = (store: Map<string, Entry>): void => {
+  ensureCacheDir();
+  writeFileSync(CACHE_FILE, JSON.stringify(Array.from(store.entries())));
+};

 export const put = (key: string, value: string, ttlMs: number): void => {
+  const store = loadStore();
   store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  saveStore(store);
 };

 export const get = (key: string): string | null => {
+  const store = loadStore();
   const entry = store.get(key);
   if (entry === undefined) return null;
   if (entry.expiresAt < Date.now()) {
     store.delete(key);
+    saveStore(store);
     return null;
   }
   return entry.value;
